interface FakeRes {
	statusCode: number;
	headers: Record<string, string | string[] | number>;
	body: Buffer[];
	ended: boolean;
	pipeFrom?: NodeJS.ReadableStream;
	writeHead(status: number, headers?: Record<string, string | string[] | number>): void;
	setHeader(n: string, v: string | string[]): void;
	getHeader(n: string): any;
	write(c: any): boolean;
	end(c?: any): void;
	on(): void;
	once(): void;
	emit(): boolean;
}

function fakeReq(opts: {
	url?: string;
	method?: string;
	cookie?: string;
	auth?: string;
	headers?: Record<string, string>;
} = {}): any {
	return {
		url: opts.url ?? "/",
		method: opts.method ?? "GET",
		headers: {
			host: "x",
			...(opts.cookie ? { cookie: opts.cookie } : {}),
			...(opts.auth ? { authorization: opts.auth } : {}),
			...opts.headers,
		},
		on() { /* no-op */ },
	};
}

function fakeRes(): FakeRes {
	const chunks: Buffer[] = [];
	const sink = new PassThrough();
	sink.on("data", c => chunks.push(Buffer.isBuffer(c) ? c : Buffer.from(c)));
	const fr: FakeRes = {
		statusCode: 0,
		headers: {},
		body: chunks,
		ended: false,
		writeHead(status, headers) {
			fr.statusCode = status;
			if (headers) for (const [k, v] of Object.entries(headers)) fr.headers[k.toLowerCase()] = v;
		},
		setHeader(n, v) { fr.headers[n.toLowerCase()] = v; },
		getHeader(n) { return fr.headers[n.toLowerCase()]; },
		write(c) {
			chunks.push(Buffer.isBuffer(c) ? c : Buffer.from(String(c)));
			return true;
		},
		end(c) {
			if (c != null) chunks.push(Buffer.isBuffer(c) ? c : Buffer.from(String(c)));
			fr.ended = true;
			sink.end();
		},
		on() { /* no-op */ },
		once() { /* no-op */ },
		emit() { return false; },
	};
	return fr;
}

function bodyText(res: FakeRes): string {
	return Buffer.concat(res.body).toString("utf-8");
}

function memoryCookieStore(): CookieStore {
	return new CookieStore(Buffer.alloc(32, 0x50));
}

function makeOpts(localhost: boolean, assetCapabilityClock?: Readonly<{ now(): number }>) {
	const store = memoryCookieStore();
	return { cookieStore: store, isLocalhost: localhost, store, assetCapabilityClock };
}

function capabilityBase(body: string, routePrefix = `/preview/${SID}/`): string {
	const matched = body.match(new RegExp(`(?:href|xml:base)="(${routePrefix}_content/[^/]+/)"`))?.[1];
	assert.ok(matched, "preview document must carry an asset capability base");
	return matched;
}

